// Embeds db/drizzle-app/*.sql into the Worker so the schema is created on first
// request. This is what lets a one-click deployment work without running
// `wrangler d1 migrations apply`. Statements are made idempotent (IF NOT EXISTS)
// so the same code also adopts databases that were migrated by wrangler earlier.
//
//   node scripts/embed-schema.mjs          write src/lib/schema-sql.generated.ts
//   node scripts/embed-schema.mjs --check  fail if the generated file is out of date

import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const dir = join(root, 'db/drizzle-app')
const out = join(root, 'app/src/lib/schema-sql.generated.ts')

function idempotent(statement) {
  return statement
    .replace(/^CREATE TABLE\s/i, 'CREATE TABLE IF NOT EXISTS ')
    .replace(/^CREATE UNIQUE INDEX\s/i, 'CREATE UNIQUE INDEX IF NOT EXISTS ')
    .replace(/^CREATE INDEX\s/i, 'CREATE INDEX IF NOT EXISTS ')
    .replace(/^CREATE TRIGGER\s/i, 'CREATE TRIGGER IF NOT EXISTS ')
}

const migrations = readdirSync(dir)
  .filter((f) => /^\d{4}_.+\.sql$/.test(f))
  .sort()
  .map((file) => {
    const text = readFileSync(join(dir, file), 'utf8')
    const statements = text
      .split('--> statement-breakpoint')
      .map((s) => s.split('\n').filter((line) => !line.trim().startsWith('--')).join('\n').trim().replace(/;$/, ''))
      .filter(Boolean)
      .map((s) => (file.startsWith('0001_') ? idempotent(s) : s))
    return { id: file.replace(/\.sql$/, ''), statements }
  })

const body = `// GENERATED by scripts/embed-schema.mjs from db/drizzle-app/*.sql. Do not edit.
export interface SchemaMigration { id: string; statements: string[] }
export const SCHEMA_MIGRATIONS: SchemaMigration[] = ${JSON.stringify(migrations, null, 2)}
`

if (process.argv.includes('--check')) {
  let current = ''
  try { current = readFileSync(out, 'utf8') } catch {}
  if (current !== body) {
    console.error('schema-sql.generated.ts is out of date. Run: node scripts/embed-schema.mjs')
    process.exit(1)
  }
} else {
  writeFileSync(out, body)
}
